//! Complete static inventory of affine residual cases generated by one queue.
//!
//! LiteRed groups parametric starts whose index vectors differ by an integer
//! translation.  Once a residual branch has been normalized as
//! `F(t) = b + A t`, that equivalence is exact equality of the ordered free
//! positions and the compact matrix `A`; the integral vector `b` is excluded
//! from the key.  This module performs only that finite census.  It does not
//! match a target, recenter a map, derive a recurrence, or apply a rule.

use std::fmt;
use std::mem::size_of;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::sync::Arc;

use symbolica::domains::integer::Integer;

use crate::{
    GeneratedSectorLiveLeafOutcome, GeneratedSectorLiveLeafQueueCertificate,
    GeneratedSectorLiveLeafQueueError, IntegralFamily, ParametricCoefficientContext,
    ResidualAffineBranchEmptyReason, ResidualAffineBranchGuardCompositionCertificate,
    ResidualAffineBranchGuardCompositionError, ResidualAffineBranchGuardCompositionLimits,
    ResidualAffineBranchSystemCertificate, ResidualAffineBranchSystemError,
    ResidualAffineBranchSystemLimits, ResidualAffineBranchSystemOutcome, ResidualAffineIntegerMap,
    ResidualProductLocusBooleanCoverCertificate, ResidualProductLocusBooleanCoverCompiler,
    ResidualProductLocusBooleanCoverError, ResidualProductLocusBooleanCoverLimits,
    ResidualProductLocusBooleanEmptyReason, ResidualProductLocusBooleanNodeOutcome,
    SymbolicSectorCaseId,
};

