pub struct GeneratedResidualAffineCaseLocator {
    work_item_ordinal: usize,
    source_case: SymbolicSectorCaseId,
    terminal_ordinal: usize,
}

impl GeneratedResidualAffineCaseLocator {
    pub const fn work_item_ordinal(self) -> usize {
        self.work_item_ordinal
    }

    pub const fn source_case(self) -> SymbolicSectorCaseId {
        self.source_case
    }

    pub const fn terminal_ordinal(self) -> usize {
        self.terminal_ordinal
    }
}

/// Exhaustive disposition of one Boolean-cover terminal.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum GeneratedResidualAffineInventoryTerminalOutcome {
    SourceCoordinateLeafProvedEmpty,
    BooleanProvedEmpty,
    AffineProvedEmpty,
    AffineUnsupported,
    GuardContradiction { first_entry_ordinal: usize },
    Actionable { case_ordinal: usize },
}

/// One source-ordered terminal and every child proof compiled for it.
#[derive(Clone, Debug)]
pub struct GeneratedResidualAffineInventoryTerminal {
    locator: GeneratedResidualAffineCaseLocator,
    source_cover: Arc<ResidualProductLocusBooleanCoverCertificate>,
    source_branch: Option<Arc<ResidualAffineBranchSystemCertificate>>,
    guard_composition: Option<Arc<ResidualAffineBranchGuardCompositionCertificate>>,
    outcome: GeneratedResidualAffineInventoryTerminalOutcome,
}

impl GeneratedResidualAffineInventoryTerminal {
    pub const fn locator(&self) -> GeneratedResidualAffineCaseLocator {
        self.locator
    }

    pub const fn source_cover(&self) -> &Arc<ResidualProductLocusBooleanCoverCertificate> {
        &self.source_cover
    }

    pub const fn source_branch(&self) -> Option<&Arc<ResidualAffineBranchSystemCertificate>> {
        self.source_branch.as_ref()
    }

    pub const fn guard_composition(
        &self,
    ) -> Option<&Arc<ResidualAffineBranchGuardCompositionCertificate>> {
        self.guard_composition.as_ref()
    }

    pub const fn outcome(&self) -> GeneratedResidualAffineInventoryTerminalOutcome {
        self.outcome
    }

    pub fn boolean_empty_reason(&self) -> Option<&ResidualProductLocusBooleanEmptyReason> {
        matches!(
            self.outcome,
            GeneratedResidualAffineInventoryTerminalOutcome::BooleanProvedEmpty
        )
        .then_some(())
        .and_then(|_| self.source_cover.nodes().get(self.locator.terminal_ordinal))
        .and_then(|node| match node.outcome() {
            ResidualProductLocusBooleanNodeOutcome::ProvedEmpty(reason) => Some(reason),
            _ => None,
        })
    }

    pub fn affine_empty_reason(&self) -> Option<&ResidualAffineBranchEmptyReason> {
        matches!(
            self.outcome,
            GeneratedResidualAffineInventoryTerminalOutcome::AffineProvedEmpty
        )
        .then_some(())
        .and_then(|_| self.source_branch.as_deref())
        .and_then(|branch| match branch.outcome() {
            ResidualAffineBranchSystemOutcome::ProvedEmpty(reason) => Some(reason),
            _ => None,
        })
    }

    pub fn affine_unsupported_reasons(
        &self,
    ) -> Option<&[crate::ResidualAffineBranchUnsupportedReason]> {
        matches!(
            self.outcome,
            GeneratedResidualAffineInventoryTerminalOutcome::AffineUnsupported
        )
        .then_some(())
        .and_then(|_| self.source_branch.as_deref())
        .and_then(|branch| match branch.outcome() {
            ResidualAffineBranchSystemOutcome::Unsupported { reasons } => Some(reasons.as_slice()),
            _ => None,
        })
    }
}

