    #[test]
    fn tampered_group_offset_fails_exact_replay() {
        let (family, context, _, inventory) = fixture();
        let mut tampered = inventory.clone();
        let offset = tampered
            .groups
            .iter_mut()
            .find_map(|group| group.anchor_offsets.first_mut())
            .and_then(|offset| offset.first_mut())
            .expect("sunset inventory retains an affine anchor offset");
        *offset = offset.clone() + Integer::from(1);
        assert_eq!(
            tampered.replay(&family, &context),
            Err(GeneratedResidualAffineCaseInventoryError::ReplayMismatch)
        );
    }

    #[test]
    fn replay_requires_exact_queue_allocation() {
        let (family, context, queue, inventory) = fixture();
        let independently_allocated_queue = Arc::new(queue.as_ref().clone());
        assert_eq!(
            inventory.replay_with_queue(&family, &context, independently_allocated_queue),
            Err(GeneratedResidualAffineCaseInventoryError::IndependentSourceQueueUnsupported)
        );
    }

    #[test]
    fn tampered_case_child_alias_fails_exact_replay() {
        let (family, context, _, inventory) = fixture();
        let mut tampered = inventory.clone();
        let case = tampered
            .cases
            .first_mut()
            .expect("sunset inventory has an actionable affine case");
        case.source_cover = Arc::new(case.source_cover.as_ref().clone());
        assert_eq!(
            tampered.replay(&family, &context),
            Err(GeneratedResidualAffineCaseInventoryError::ReplayMismatch)
        );
    }

    #[test]
    fn terminal_lower_bound_is_checked_before_initial_reserve() {
        let (family, context, queue, _) = fixture();
        let work_items = queue.work_items().len();
        assert!(work_items > 0);
        let mut limits = GeneratedResidualAffineCaseInventoryLimits::default();
        limits.max_terminals = work_items - 1;
        assert!(matches!(
            GeneratedResidualAffineCaseInventoryCompiler::compile(
                &family,
                &context,
                queue,
                limits,
            ),
            Err(GeneratedResidualAffineCaseInventoryError::ResourceLimit {
                resource: "terminals",
                requested,
                limit,
            }) if requested == work_items && limit + 1 == requested
        ));
    }

    #[test]
    fn scope_preflight_is_exact_and_bounds_supplied_operands_before_mismatch_replay() {
        let (family, context, queue, _) = fixture();
        let family_bytes = queue
            .family_fingerprint()
            .len()
            .max(family.fingerprint_ref().len());
        let context_bytes = queue
            .context_fingerprint()
            .len()
            .max(context.fingerprint().len());
        let scope_bytes = queue
            .family_fingerprint()
            .len()
            .checked_add(family.fingerprint_ref().len())
            .and_then(|bytes| bytes.checked_add(queue.context_fingerprint().len()))
            .and_then(|bytes| bytes.checked_add(context.fingerprint().len()))
            .unwrap();
        let mut exact_scope = GeneratedResidualAffineCaseInventoryLimits::default();
        exact_scope.max_family_fingerprint_bytes = family_bytes;
        exact_scope.max_context_fingerprint_bytes = context_bytes;
        exact_scope.max_scope_fingerprint_comparison_bytes = scope_bytes;
        let exactly_bounded = GeneratedResidualAffineCaseInventoryCompiler::compile(
            &family,
            &context,
            queue.clone(),
            exact_scope,
        )
        .unwrap();
        assert_eq!(
            exactly_bounded.stats().family_fingerprint_bytes(),
            family_bytes
        );
        assert_eq!(
            exactly_bounded.stats().context_fingerprint_bytes(),
            context_bytes
        );
        assert_eq!(
            exactly_bounded.stats().scope_fingerprint_comparison_bytes(),
            scope_bytes
        );
        exactly_bounded.replay(&family, &context).unwrap();

        let mut scope_one_below = exact_scope;
        scope_one_below.max_scope_fingerprint_comparison_bytes = scope_bytes - 1;
        assert!(matches!(
            GeneratedResidualAffineCaseInventoryCompiler::compile(
                &family,
                &context,
                queue.clone(),
                scope_one_below,
            ),
            Err(GeneratedResidualAffineCaseInventoryError::ResourceLimit {
                resource: "scope fingerprint comparison bytes",
                requested,
                limit,
            }) if requested == scope_bytes && limit + 1 == requested
        ));

        let wrong_family = equal_mass_sunset(&format!(
            "affine-case-inventory-wrong-family-{}",
            "x".repeat(1024)
        ));
        assert!(wrong_family.fingerprint_ref().len() > family_bytes);
        let expected_wrong_family_bytes = wrong_family.fingerprint_ref().len();
        for result in [
            GeneratedResidualAffineCaseInventoryCompiler::compile(
                &wrong_family,
                &context,
                queue.clone(),
                exact_scope,
            )
            .map(|_| ()),
            exactly_bounded.replay(&wrong_family, &context),
        ] {
            assert!(matches!(
                result,
                Err(GeneratedResidualAffineCaseInventoryError::ResourceLimit {
                    resource: "family fingerprint bytes",
                    requested,
                    limit,
                }) if requested == expected_wrong_family_bytes && limit == family_bytes
            ));
        }

        let wrong_context = ParametricCoefficientContext::try_new(
            family.coefficient_context(),
            &format!("affine-case-inventory-wrong-context-{}", "y".repeat(1024)),
            context.index_count(),
        )
        .unwrap();
        assert!(wrong_context.fingerprint().len() > context_bytes);
        let expected_wrong_context_bytes = wrong_context.fingerprint().len();
        for result in [
            GeneratedResidualAffineCaseInventoryCompiler::compile(
                &family,
                &wrong_context,
                queue.clone(),
                exact_scope,
            )
            .map(|_| ()),
            exactly_bounded.replay(&family, &wrong_context),
        ] {
            assert!(matches!(
                result,
                Err(GeneratedResidualAffineCaseInventoryError::ResourceLimit {
                    resource: "context fingerprint bytes",
                    requested,
                    limit,
                }) if requested == expected_wrong_context_bytes && limit == context_bytes
            ));
        }
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    struct ExpectedRecursiveChildComparison {
        comparisons: usize,
        units: usize,
        owned_bytes: usize,
        integer_bits: usize,
        integer_system_calls: usize,
        integer_system_verification_units: usize,
        integer_system_bit_work: usize,
        unsupported_retained_integer_system_calls: usize,
    }

    impl ExpectedRecursiveChildComparison {
        fn charge(&mut self, units: usize, owned_bytes: usize, integer_bits: usize) {
            self.comparisons = self.comparisons.checked_add(1).unwrap();
            self.units = self.units.checked_add(units).unwrap();
            self.owned_bytes = self.owned_bytes.checked_add(owned_bytes).unwrap();
            self.integer_bits = self.integer_bits.checked_add(integer_bits).unwrap();
        }

        fn cover(&mut self, cover: &ResidualProductLocusBooleanCoverCertificate) {
            self.charge(
                cover.stats().payload_comparison_units(),
                cover.stats().payload_comparison_bytes(),
                0,
            );
        }

        fn branch(&mut self, branch: &ResidualAffineBranchSystemCertificate) {
            self.charge(
                branch.stats().payload_comparison_units(),
                branch.stats().payload_comparison_bytes(),
                branch.stats().payload_comparison_integer_bits(),
            );
            self.cover(branch.source_cover());
            if let Some(system) = branch
                .retained_integer_system_for_payload_comparison()
                .as_deref()
            {
                let limits = system.limits();
                self.charge(
                    limits.max_verification_operations,
                    0,
                    limits.max_integer_bit_work,
                );
                self.integer_system_calls += 1;
                self.integer_system_verification_units = self
                    .integer_system_verification_units
                    .checked_add(limits.max_verification_operations)
                    .unwrap();
                self.integer_system_bit_work = self
                    .integer_system_bit_work
                    .checked_add(limits.max_integer_bit_work)
                    .unwrap();
                if matches!(
                    branch.outcome(),
                    ResidualAffineBranchSystemOutcome::Unsupported { .. }
                ) {
                    assert!(
                        branch.integer_system().is_none(),
                        "the public semantic accessor must remain outcome-gated"
                    );
                    assert!(
                        system.affine_map().is_some(),
                        "the unsupported recognized subset must retain its diagnostic partial map"
                    );
                    self.unsupported_retained_integer_system_calls += 1;
                }
            }
        }

        fn guard(&mut self, guard: &ResidualAffineBranchGuardCompositionCertificate) {
            self.charge(
                guard.stats().payload_comparison_units(),
                guard.stats().payload_comparison_bytes(),
                guard.stats().payload_comparison_integer_bits(),
            );
            self.cover(guard.source_cover());
            self.branch(guard.source_branch());
        }
    }

    fn expected_recursive_child_comparison(
        inventory: &GeneratedResidualAffineCaseInventoryCertificate,
    ) -> ExpectedRecursiveChildComparison {
        let mut expected = ExpectedRecursiveChildComparison::default();
        let mut previous_work_item = None;
        for terminal in inventory.terminals() {
            let work_item = terminal.locator().work_item_ordinal();
            if previous_work_item != Some(work_item) {
                expected.cover(terminal.source_cover());
                previous_work_item = Some(work_item);
            }
            if let Some(guard) = terminal.guard_composition() {
                expected.guard(guard);
            } else if let Some(branch) = terminal.source_branch() {
                expected.branch(branch);
            }
        }
        expected
    }

    #[test]
    fn unsupported_retained_partial_map_is_charged_by_exact_recursive_limits() {
        let (family, context, queue, inventory) = unsupported_partial_map_fixture();
        let expected = expected_recursive_child_comparison(&inventory);
        assert!(expected.integer_system_calls > 0);
        assert!(expected.integer_system_verification_units > 0);
        assert!(expected.integer_system_bit_work > 0);
        assert!(expected.unsupported_retained_integer_system_calls > 0);

        let stats = inventory.stats();
        assert_eq!(
            stats.recursive_child_payload_comparisons(),
            expected.comparisons
        );
        assert_eq!(
            stats.recursive_child_payload_comparison_units(),
            expected.units
        );
        assert_eq!(
            stats.recursive_child_owned_payload_comparison_bytes(),
            expected.owned_bytes
        );
        assert_eq!(
            stats.recursive_child_payload_comparison_integer_bit_work(),
            expected.integer_bits
        );

        let mut exact = GeneratedResidualAffineCaseInventoryLimits::default();
        exact.max_recursive_child_payload_comparisons = expected.comparisons;
        exact.max_recursive_child_payload_comparison_units = expected.units;
        exact.max_recursive_child_owned_payload_comparison_bytes = expected.owned_bytes;
        exact.max_recursive_child_payload_comparison_integer_bit_work = expected.integer_bits;
        let exactly_bounded = GeneratedResidualAffineCaseInventoryCompiler::compile(
            &family,
            &context,
            queue.clone(),
            exact,
        )
        .unwrap();
        exactly_bounded.replay(&family, &context).unwrap();

        for (resource, limited) in [
            (
                "recursive child payload comparisons",
                GeneratedResidualAffineCaseInventoryLimits {
                    max_recursive_child_payload_comparisons: expected.comparisons - 1,
                    ..exact
                },
            ),
            (
                "recursive child payload comparison units",
                GeneratedResidualAffineCaseInventoryLimits {
                    max_recursive_child_payload_comparison_units: expected.units - 1,
                    ..exact
                },
            ),
            (
                "recursive child payload comparison integer-bit work",
                GeneratedResidualAffineCaseInventoryLimits {
                    max_recursive_child_payload_comparison_integer_bit_work: expected.integer_bits
                        - 1,
                    ..exact
                },
            ),
        ] {
            assert!(matches!(
                GeneratedResidualAffineCaseInventoryCompiler::compile(
                    &family,
                    &context,
                    queue.clone(),
                    limited,
                ),
                Err(GeneratedResidualAffineCaseInventoryError::ResourceLimit {
                    resource: actual,
                    ..
                }) if actual == resource
            ));
        }
    }

    #[test]
    fn aggregate_limits_fail_at_exact_one_below_boundaries() {
        let (family, context, queue, inventory) = fixture();
        let stats = inventory.stats();
        let mut exact = GeneratedResidualAffineCaseInventoryLimits::default();
        exact.max_family_fingerprint_bytes = stats.family_fingerprint_bytes();
        exact.max_context_fingerprint_bytes = stats.context_fingerprint_bytes();
        exact.max_scope_fingerprint_comparison_bytes = stats.scope_fingerprint_comparison_bytes();
        exact.max_work_items = stats.work_items();
        exact.max_cover_nodes = stats.cover_nodes();
        exact.max_total_cover_nodes = stats.cover_nodes();
        exact.max_total_cover_retained_state_bytes = stats.cover_retained_state_bytes();
        exact.max_terminals = stats.terminals();
        exact.max_branch_compilations = stats.branch_compilations();
        exact.max_guard_compositions = stats.guard_compositions();
        exact.max_source_empty_terminals = stats.source_empty_terminals();
        exact.max_boolean_empty_terminals = stats.boolean_empty_terminals();
        exact.max_affine_empty_terminals = stats.affine_empty_terminals();
        exact.max_unsupported_terminals = stats.unsupported_terminals();
        exact.max_guard_contradictions = stats.guard_contradictions();
        exact.max_actionable_cases = stats.actionable_cases();
        exact.max_total_branch_referenced_atom_terms = stats.branch_referenced_atom_terms();
        exact.max_total_branch_potential_retained_integer_bits =
            stats.branch_potential_retained_integer_bits();
        exact.max_total_guard_output_terms = stats.guard_output_terms();
        exact.max_total_guard_integer_bit_work = stats.guard_integer_bit_work();
        exact.max_total_guard_retained_origin_bytes = stats.guard_retained_origin_bytes();
        exact.max_free_position_references = stats.free_position_references();
        exact.max_compact_matrix_entries_inspected = stats.compact_matrix_entries_inspected();
        exact.max_retained_compact_matrix_entries = stats.retained_compact_matrix_entries();
        exact.max_constant_entries = stats.constant_entries();
        exact.max_affine_integer_bits_inspected = stats.affine_integer_bits_inspected();
        exact.max_retained_affine_integer_bits = stats.retained_affine_integer_bits();
        exact.max_group_comparisons = stats.group_comparisons();
        exact.max_group_comparison_entries_inspected = stats.group_comparison_entries_inspected();
        exact.max_group_comparison_integer_bit_work = stats.group_comparison_integer_bit_work();
        exact.max_groups = stats.groups();
        exact.max_group_case_references = stats.group_case_references();
        exact.max_cases_per_group = inventory
            .groups()
            .iter()
            .map(|group| group.case_ordinals().len())
            .max()
            .unwrap_or(0);
        exact.max_anchor_offset_entries = stats.anchor_offset_entries();
        exact.max_anchor_offset_integer_bit_work = stats.anchor_offset_integer_bit_work();
        exact.max_anchor_offset_integer_bits = stats.anchor_offset_integer_bits();
        exact.max_payload_comparison_units = stats.payload_comparison_units();
        exact.max_payload_comparison_bytes = stats.payload_comparison_bytes();
        exact.max_payload_comparison_integer_bits = stats.payload_comparison_integer_bits();
        exact.max_recursive_child_payload_comparisons = stats.recursive_child_payload_comparisons();
        exact.max_recursive_child_payload_comparison_units =
            stats.recursive_child_payload_comparison_units();
        exact.max_recursive_child_owned_payload_comparison_bytes =
            stats.recursive_child_owned_payload_comparison_bytes();
        exact.max_recursive_child_payload_comparison_integer_bit_work =
            stats.recursive_child_payload_comparison_integer_bit_work();

        let exactly_bounded = GeneratedResidualAffineCaseInventoryCompiler::compile(
            &family,
            &context,
            queue.clone(),
            exact,
        )
        .unwrap();
        exactly_bounded.replay(&family, &context).unwrap();
        assert_eq!(exactly_bounded.stats(), stats);
        assert_eq!(exactly_bounded.groups, inventory.groups);
        assert_eq!(exactly_bounded.terminals.len(), inventory.terminals.len());
        for (left, right) in exactly_bounded
            .terminals
            .iter()
            .zip(inventory.terminals.iter())
        {
            assert_eq!(left.locator, right.locator);
            assert_eq!(left.outcome, right.outcome);
        }
        assert_eq!(exactly_bounded.cases.len(), inventory.cases.len());
        for (left, right) in exactly_bounded.cases.iter().zip(inventory.cases.iter()) {
            assert_eq!(left.ordinal, right.ordinal);
            assert_eq!(left.locator, right.locator);
            assert_eq!(left.group_ordinal, right.group_ordinal);
            assert_eq!(left.ordinal_within_group, right.ordinal_within_group);
            assert_eq!(left.constants, right.constants);
        }

        macro_rules! one_below {
            ($field:ident, $observed:expr, $resource:literal) => {{
                let observed = $observed;
                assert!(observed > 0, "{} census must be nonzero", $resource);
                let mut limited = exact;
                limited.$field = observed - 1;
                assert!(matches!(
                    GeneratedResidualAffineCaseInventoryCompiler::compile(
                        &family,
                        &context,
                        queue.clone(),
                        limited,
                    ),
                    Err(GeneratedResidualAffineCaseInventoryError::ResourceLimit {
                        resource: $resource,
                        ..
                    })
                ));
            }};
        }

        one_below!(
            max_family_fingerprint_bytes,
            stats.family_fingerprint_bytes(),
            "family fingerprint bytes"
        );
        one_below!(
            max_context_fingerprint_bytes,
            stats.context_fingerprint_bytes(),
            "context fingerprint bytes"
        );
        one_below!(
            max_scope_fingerprint_comparison_bytes,
            stats.scope_fingerprint_comparison_bytes(),
            "scope fingerprint comparison bytes"
        );
        one_below!(max_work_items, stats.work_items(), "work items");
        one_below!(max_terminals, stats.terminals(), "terminals");
        one_below!(
            max_total_cover_nodes,
            stats.cover_nodes(),
            "total cover nodes"
        );
        one_below!(
            max_total_cover_retained_state_bytes,
            stats.cover_retained_state_bytes(),
            "total cover retained state bytes"
        );
        one_below!(
            max_retained_affine_integer_bits,
            stats.retained_affine_integer_bits(),
            "retained affine integer bits"
        );
        one_below!(
            max_group_comparisons,
            stats.group_comparisons(),
            "affine geometry group comparisons"
        );
        one_below!(
            max_group_comparison_entries_inspected,
            stats.group_comparison_entries_inspected(),
            "affine geometry comparison entries inspected"
        );
        one_below!(
            max_group_comparison_integer_bit_work,
            stats.group_comparison_integer_bit_work(),
            "affine geometry comparison integer-bit work"
        );
        one_below!(
            max_anchor_offset_entries,
            stats.anchor_offset_entries(),
            "anchor offset entries"
        );
        one_below!(
            max_anchor_offset_integer_bits,
            stats.anchor_offset_integer_bits(),
            "anchor offset integer bits"
        );
        one_below!(
            max_payload_comparison_units,
            stats.payload_comparison_units(),
            "payload comparison units"
        );
        one_below!(
            max_payload_comparison_bytes,
            stats.payload_comparison_bytes(),
            "payload comparison bytes"
        );
        one_below!(
            max_payload_comparison_integer_bits,
            stats.payload_comparison_integer_bits(),
            "payload comparison integer bits"
        );
        one_below!(
            max_recursive_child_payload_comparisons,
            stats.recursive_child_payload_comparisons(),
            "recursive child payload comparisons"
        );
        one_below!(
            max_recursive_child_payload_comparison_units,
            stats.recursive_child_payload_comparison_units(),
            "recursive child payload comparison units"
        );
        one_below!(
            max_recursive_child_owned_payload_comparison_bytes,
            stats.recursive_child_owned_payload_comparison_bytes(),
            "recursive child-owned payload comparison bytes"
        );
        one_below!(
            max_recursive_child_payload_comparison_integer_bit_work,
            stats.recursive_child_payload_comparison_integer_bit_work(),
            "recursive child payload comparison integer-bit work"
        );
    }
